import 'server-only';
import ExcelJS from 'exceljs';

/**
 * The shared mechanics behind every bulk-upload template.
 *
 * Extracted when the fifth of these appeared. The templates differ in their
 * columns, their dropdowns and their instructions; they do not differ in how a
 * header row is styled, how a list is written to a Lists sheet, or how a column
 * index becomes a letter. Five copies of `colLetter` is five places for an
 * off-by-one to hide.
 *
 * Safe to extract because each existing template has a round-trip test that
 * reads the generated bytes back and asserts the validations survived — so a
 * mistake here fails a test rather than shipping a workbook that looks fine.
 */

export const TEMPLATE_FONT = 'Arial';

/** Cells the person fills in. Paired with the legend every guide sheet carries. */
export const INPUT_FILL: ExcelJS.Fill = {
  type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFFFDE7' },
};

export const HEADER_FILL: ExcelJS.Fill = {
  type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF065F46' },
};

export const EXAMPLE_FONT: Partial<ExcelJS.Font> = {
  name: TEMPLATE_FONT, italic: true, color: { argb: 'FF9CA3AF' },
};

/** 1-based column index to its spreadsheet letter. */
export function colLetter(n: number): string {
  let s = '';
  while (n > 0) {
    const r = (n - 1) % 26;
    s = String.fromCharCode(65 + r) + s;
    n = Math.floor((n - 1) / 26);
  }
  return s;
}

/**
 * Write a titled column of values to a Lists sheet and return its range.
 *
 * The range is clamped to at least one row even when `values` is empty: an
 * Excel data validation pointing at a zero-height range is malformed, and the
 * file opens with a repair prompt rather than a visible error.
 */
export function writeList(
  sheet: ExcelJS.Worksheet,
  column: number,
  title: string,
  values: string[],
): string {
  const letter = colLetter(column);
  const head = sheet.getCell(`${letter}1`);
  head.value = title;
  head.font = { name: TEMPLATE_FONT, bold: true, size: 10 };

  values.forEach((v, i) => {
    const c = sheet.getCell(`${letter}${i + 2}`);
    c.value = v;
    c.font = { name: TEMPLATE_FONT, size: 10 };
  });

  sheet.getColumn(column).width = Math.max(18, title.length + 4);
  return `Lists!$${letter}$2:$${letter}$${Math.max(values.length + 1, 2)}`;
}

/**
 * A dropdown bound to a range.
 *
 * `strict` decides whether Excel refuses a typed value, and the choice is not
 * cosmetic. Use `true` where the column has a database CHECK behind it, so a
 * wrong value is caught at typing time rather than arriving as a constraint
 * violation naming no row. Use `false` where the list is a convenience and a
 * value outside it is legitimate — a country the list forgot, a parent defined
 * elsewhere in the same file.
 */
export function listRule(
  range: string,
  prompt: string,
  strict = true,
): ExcelJS.DataValidation {
  return {
    type: 'list',
    allowBlank: true,
    showErrorMessage: strict,
    formulae: [`=${range}`],
    errorTitle: 'Choose from the list',
    error: prompt,
  };
}

/** Style the header row and freeze it, with an autofilter across the columns. */
export function styleHeader(sheet: ExcelJS.Worksheet, columnCount: number): void {
  const header = sheet.getRow(1);
  header.font = { name: TEMPLATE_FONT, bold: true, color: { argb: 'FFFFFFFF' }, size: 11 };
  header.fill = HEADER_FILL;
  header.height = 22;
  header.alignment = { vertical: 'middle' };
  sheet.views = [{ state: 'frozen', ySplit: 1 }];
  sheet.autoFilter = { from: { row: 1, column: 1 }, to: { row: 1, column: columnCount } };
}

export type GuideLine = [text: string, kind: 'h' | 'p'];

/**
 * Write an instructions sheet and its legend.
 *
 * Every template ends with the same legend because the shading is the only
 * visual convention these files rely on, and a reader who has not been told what
 * it means will edit a formula column.
 */
export function writeGuide(sheet: ExcelJS.Worksheet, lines: GuideLine[]): void {
  sheet.getColumn(1).width = 96;

  lines.forEach(([text, kind], i) => {
    const cell = sheet.getCell(`A${i + 1}`);
    cell.value = text;
    cell.font = kind === 'h'
      ? { name: TEMPLATE_FONT, bold: true, size: 12 }
      : { name: TEMPLATE_FONT, size: 11 };
    cell.alignment = { wrapText: true, vertical: 'top' };
  });

  const legend = lines.length + 2;
  const cell = sheet.getCell(`A${legend}`);
  cell.value = 'Cells shaded like this are yours to fill in.';
  cell.fill = INPUT_FILL;
  cell.font = { name: TEMPLATE_FONT, size: 11 };
}

/** A non-negative number, optionally bounded above. */
export function numberRule(
  message: string,
  min = 0,
  max?: number,
): ExcelJS.DataValidation {
  return max === undefined
    ? {
      type: 'decimal', operator: 'greaterThanOrEqual', allowBlank: true,
      showErrorMessage: true, formulae: [min],
      errorTitle: 'Enter a number', error: message,
    }
    : {
      type: 'decimal', operator: 'between', allowBlank: true,
      showErrorMessage: true, formulae: [min, max],
      errorTitle: 'Enter a number', error: message,
    };
}

/** An ISO date, which is the only format the importers accept. */
export function dateRule(): ExcelJS.DataValidation {
  return {
    type: 'date', operator: 'greaterThan', allowBlank: true,
    showErrorMessage: true, formulae: [new Date(2000, 0, 1)],
    errorTitle: 'Enter a date',
    error: 'Use a real date. It is stored as YYYY-MM-DD.',
  };
}
